import csv
import os

def process_data():
    total = 0.0
    if not os.path.isfile('data.csv'):
        print(total)
        return
    with open('data.csv', newline='', encoding='utf-8') as csvfile:
        reader = csv.DictReader(csvfile)
        for row in reader:
            try:
                total += float(row.get('amount', 0))
            except (ValueError, TypeError):
                continue
    print(total)

if __name__ == '__main__':
    process_data()
